RL.modalRoot = function () {
  let root = null;
  try { root = document.querySelector('dialog:modal'); } catch (e) { /* :modal unsupported */ }
  if (root) return root;
  for (const el of document.querySelectorAll('[aria-modal="true"]')) if (!RL.isDevTool(el) && isVisible(el) && el.getClientRects().length) root = el;
  return root;
};
// Is n outside the open modal (neither inside it nor one of its ancestors)?
// (composed tree: shadow roots count as part of their host)
const behindModal = (modal, n) => {
  if (!modal) return false;
  for (let e = n; e; e = e.parentNode || e.host) if (e === modal) return false;
  for (let e = modal; e; e = e.parentNode || e.host) if (e === n) return false;
  return true;
};
RL.behindModal = behindModal;
RL.inScope = function () {
  const modal = RL.modalRoot();
  return modal ? (n) => !behindModal(modal, n) : () => true;
};

RL.allElements = function () {
  const out = [];
  const walk = (root) => {
    const it = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT, {
      acceptNode: (n) => RL.isDevTool(n) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT,
    });
    for (let n = it.currentNode; n; n = it.nextNode()) {
      if (n.nodeType === 1) { out.push(n); if (n.shadowRoot) walk(n.shadowRoot); }
    }
  };
  walk(document.body);
  return out;
};

RL.collectText = function () {
  const items = [];
  const range = document.createRange();
  const modal = RL.modalRoot();
  const visit = (root) => {
    const it = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT, {
      acceptNode: (n) => {
        if (n.nodeType === 1) return RL.isDevTool(n) || behindModal(modal, n) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_SKIP;
        return /\S/.test(n.textContent) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
      },
    });
    let n;
    while ((n = it.nextNode())) {
      const el = n.parentElement || (n.parentNode && n.parentNode.host);
      if (!el || !isVisible(el)) continue;
      range.selectNodeContents(n);
      const rects = Array.from(range.getClientRects()).filter((r) => r.width > 0.5 && r.height > 0.5).map(docRect);
      if (!rects.length) continue;
      const clip = RL.clipBoxOf(el);
      const vis = clip ? rects.map((r) => intersect(r, clip)).filter(Boolean) : rects;
      if (!vis.length || vis.every((r) => r.w < 1 || r.h < 1)) continue; // fully clipped away (carousel slide, collapsed panel)
      items.push({ node: n, el, rects, vis, box: unionRects(rects), text: n.textContent.replace(/\s+/g, ' ').trim() });
    }
    // shadow roots
    root.querySelectorAll && root.querySelectorAll('*').forEach((e) => { if (e.shadowRoot && !RL.isDevTool(e) && !e.closest('nextjs-portal,vite-error-overlay,astro-dev-toolbar')) visit(e.shadowRoot); });
  };
  visit(document.body);
  return items;
};

// Region an element's *content* can paint into: the intersection of its own
// overflow clip and every ancestor's. null = unclipped.
const clipCache = new Map();
RL.clipBoxOf = function (el) {
  if (!el || el === document.documentElement || el === document.body) return null;
  if (clipCache.has(el)) return clipCache.get(el);
  const s = cs(el);
  let box = s.position === 'fixed' ? null : RL.clipBoxOf(parentOf(el));
  const isSvg = el.namespaceURI === 'http://www.w3.org/2000/svg';
  if ((!isSvg || el.tagName.toLowerCase() === 'svg') && (s.overflowX !== 'visible' || s.overflowY !== 'visible')) {
    const r = docRect(el.getBoundingClientRect());
    const own = {
      x: s.overflowX !== 'visible' ? r.x : -1e9, right: s.overflowX !== 'visible' ? r.right : 1e9,
      y: s.overflowY !== 'visible' ? r.y : -1e9, bottom: s.overflowY !== 'visible' ? r.bottom : 1e9,
    };
    own.w = own.right - own.x; own.h = own.bottom - own.y;
    box = box ? (intersect(box, own) || { x: 0, y: 0, w: 0, h: 0, right: 0, bottom: 0 }) : own;
  }
  clipCache.set(el, box);
  return box;
};

RL.isInteractive = function (el) {
  const tag = el.tagName.toLowerCase();
  if (tag === 'button' || tag === 'select' || tag === 'textarea' || tag === 'summary') return true;
  if (tag === 'a' && el.hasAttribute('href')) return true;
  if (tag === 'input' && el.type !== 'hidden') return true;
  const role = el.getAttribute('role');
  if (role && /^(button|link|checkbox|radio|switch|tab|menuitem|option|slider|combobox)$/.test(role)) return true;
  return false;
};

RL.isDisabled = function (el) {
  for (let n = el; n; n = parentOf(n)) {
    if (n.nodeType === 1 && (n.disabled || n.getAttribute('aria-disabled') === 'true')) return true;
    if (n.tagName === 'FIELDSET' && n.disabled) return true;
  }
  return false;
};

// Stack of elements at a document point. Scrolls the window if the point is
// outside the viewport (elementsFromPoint only works for visible points).
RL.stackAt = function (x, y) {
  const vy = y - scrollY, vx = x - scrollX;
  if (vy < 0 || vy >= innerHeight || vx < 0 || vx >= innerWidth) {
    if (RL.options.noScroll) return { stack: [], scrolled: scrollY !== 0 || scrollX !== 0 };
    window.scrollTo({ left: Math.max(0, x - innerWidth / 2), top: Math.max(0, y - innerHeight / 2), behavior: 'instant' });
  }
  return { stack: document.elementsFromPoint(x - scrollX, y - scrollY), scrolled: scrollY !== 0 || scrollX !== 0 };
};

// Colors inside a gradient: every stop must be (mostly) opaque for the layer to hide what is beneath.
const COLOR_TOKEN = /(?:rgba?|hsla?|oklch|oklab|lab|lch|color|hwb)\([^()]*\)|#[0-9a-f]{3,8}\b|\btransparent\b/gi;
function gradientOpaque(img) {
  if (/url\(/.test(img)) return true;
  const stops = img.match(COLOR_TOKEN) || [];
  if (!stops.length) return false;
  return stops.every((c) => { const p = parseColor(c); return p && p.a >= 0.6; });
}

RL.isOpaqueLayer = function (el) {
  const tag = el.tagName.toLowerCase();
  if (tag === 'img' || tag === 'video' || tag === 'canvas' || tag === 'picture') return effectiveOpacity(el) > 0.5;
  const s = cs(el);
  const bg = parseColor(s.backgroundColor);
  const glass = s.backdropFilter && s.backdropFilter !== 'none' && bg && bg.a > 0.1;
  if ((bg && bg.a >= 0.5) || glass || (s.backgroundImage && s.backgroundImage !== 'none' && gradientOpaque(s.backgroundImage))) {
    return effectiveOpacity(el) > 0.5;
  }
  return false;
};

// Element sits in a deliberately layered composition (absolute/transform/offset)
// between itself and `stop` (exclusive).
RL.layeredBetween = function (el, stop) {
  for (let n = el; n && n !== stop; n = parentOf(n)) {
    const s = cs(n);
    if (s.position === 'absolute' || s.position === 'fixed') return true;
    if (s.transform !== 'none' || (s.translate && s.translate !== 'none') || (s.rotate && s.rotate !== 'none') || (s.scale && s.scale !== 'none')) return true;
    if (s.position === 'relative' && ((parseFloat(s.top) || 0) !== 0 || (parseFloat(s.left) || 0) !== 0)) return true;
  }
  return false;
};

RL.commonAncestor = function (a, b) {
  const set = new Set();
  for (let n = a; n; n = parentOf(n)) set.add(n);
  for (let n = b; n; n = parentOf(n)) if (set.has(n)) return n;
  return null;
};

RL.fixedAncestor = function (el) {
  for (let n = el; n; n = parentOf(n)) {
    const p = cs(n).position;
    if (p === 'fixed' || p === 'sticky') return n;
  }
  return null;
};

// ---- rules/layout.js
// Layout rules: text and boxes escaping their containers, viewport overflow,
// accidental scrollbars.

const SVG_NS = 'http://www.w3.org/2000/svg';

function borders(el) {
  const s = RL.cs(el);
  return { t: parseFloat(s.borderTopWidth) || 0, r: parseFloat(s.borderRightWidth) || 0,
    b: parseFloat(s.borderBottomWidth) || 0, l: parseFloat(s.borderLeftWidth) || 0 };
}

function paddingBox(el) {
  const r = RL.rectOf(el), b = borders(el);
  return { x: r.x + b.l, y: r.y + b.t, right: r.right - b.r, bottom: r.bottom - b.b, w: r.w - b.l - b.r, h: r.h - b.t - b.b };
}
RL.paddingBox = paddingBox;

function overflowBeyond(rects, box) {
  const o = { left: 0, right: 0, top: 0, bottom: 0 };
  for (const r of rects) {
    o.left = Math.max(o.left, box.x - r.x);
    o.right = Math.max(o.right, r.right - box.right);
    o.top = Math.max(o.top, box.y - r.y);
    o.bottom = Math.max(o.bottom, r.bottom - box.bottom);
  }
  return o;
}

function fontSize(el) { return parseFloat(RL.cs(el).fontSize) || 16; }

function fmtOver(o, tolX, tolY) {
  const parts = [];
  if (o.right > tolX) parts.push(Math.round(o.right) + 'px past the right edge');
  if (o.left > tolX) parts.push(Math.round(o.left) + 'px past the left edge');
  if (o.bottom > tolY) parts.push(Math.round(o.bottom) + 'px past the bottom');
  if (o.top > tolY) parts.push(Math.round(o.top) + 'px past the top');
  return parts.join(', ');
}

function isIntentionalTruncation(textEl, clipper, axis) {
  for (let n = textEl; n; n = RL.parentOf(n)) {
    const s = RL.cs(n);
    if (axis === 'x' && s.textOverflow === 'ellipsis') return true;
    if (s.webkitLineClamp && s.webkitLineClamp !== 'none') return true;
    if (s.maskImage && s.maskImage !== 'none') return true;
    if (s.webkitMaskImage && s.webkitMaskImage !== 'none') return true;
    if (n === clipper) break;
  }
  return false;
}

// ---------------------------------------------------------------------------
RL.rule({
  id: 'text-overflow',
  run(ctx) {
    const seen = new Set();
    for (const t of ctx.texts) {
      if (RL.isIgnored(t.el, 'text-overflow')) continue;
      const block = RL.nearestBlock(t.el);
      if (block.namespaceURI === SVG_NS) continue; // svg text is handled by text-clipped
      const fs = fontSize(t.el);
      const tolX = 1.5, tolY = Math.max(2, fs * 0.3);
      let needX = true, needY = true;
      for (let n = block, d = 0; n && n !== document.body && n !== document.documentElement && d < 40 && (needX || needY); n = RL.parentOf(n), d++) {
        if (RL.clips(n, 'x') || RL.clips(n, 'y')) break; // clipping is text-clipped's job
        const sides = RL.boundarySides(n);
        if (sides) {
          const o = overflowBeyond(t.rects, paddingBox(n));
          const cx = needX && sides.x, cy = needY && sides.y;
          if (!cx) { o.left = 0; o.right = 0; }
          if (!cy) { o.top = 0; o.bottom = 0; }
          for (const k of ['top', 'right', 'bottom', 'left']) if (!sides[k]) o[k] = 0; // past an edge that isn't drawn
          if (sides.x) needX = false;
          if (sides.y) needY = false;
          if ((o.left > tolX || o.right > tolX || o.top > tolY || o.bottom > tolY) && !seen.has(n)) {
            seen.add(n);
            const own = n === block;
            ctx.report({
              rule: 'text-overflow', el: t.el, related: own ? undefined : n,
              message: 'Text spills outside its ' + (own ? 'box' : 'container') + ' (' + fmtOver(o, tolX, tolY) + ').',
              details: { overflow: o, whiteSpace: RL.cs(t.el).whiteSpace, overflowWrap: RL.cs(block).overflowWrap },
            });
            break;
          }
        }
        if (RL.isOutOfFlow(n)) break;
      }
    }
  },
});

// Text that still fits inside the box but has eaten its side padding and nearly
// touches the border: the box was designed with room, the content outgrew it.
RL.rule({
  id: 'text-crowding',
  run(ctx) {
    const seen = new Set();
    for (const t of ctx.texts) {
      if (RL.isIgnored(t.el, 'text-crowding') || RL.flagged.has(t.el)) continue;
      const block = RL.nearestBlock(t.el);
      if (block.namespaceURI === SVG_NS) continue;
      for (let n = block, d = 0; n && n !== document.body && n !== document.documentElement && d < 6; n = RL.parentOf(n), d++) {
        const sides = !RL.isInline(n) && RL.boundarySides(n);
        if (sides && sides.x) {
          const s = RL.cs(n);
          const pl = parseFloat(s.paddingLeft) || 0, pr = parseFloat(s.paddingRight) || 0;
          const box = paddingBox(n);
          const minX = Math.min(...t.rects.map((r) => r.x)), maxX = Math.max(...t.rects.map((r) => r.right));
          const gapL = minX - box.x, gapR = box.right - maxX;
          // Only boxes designed with side padding; text past the padding box is text-overflow's job.
          const side = pr >= 8 && gapR > -1.5 && gapR < Math.min(4, pr * 0.35) ? 'right' : pl >= 8 && gapL > -1.5 && gapL < Math.min(4, pl * 0.35) ? 'left' : null;
          if (side && !seen.has(n) && box.w < innerWidth - 4) {
            seen.add(n);
            const gap = Math.max(0, Math.round(side === 'right' ? gapR : gapL));
            ctx.report({
              rule: 'text-crowding', el: t.el, related: n === block ? undefined : n,
              message: 'Text has run through the box\'s ' + Math.round(side === 'right' ? pr : pl) + 'px ' + side + ' padding and sits ' + gap + 'px from its edge.',
              details: { side, gap, padding: side === 'right' ? pr : pl },
            });
          }
          break;
        }
        if (RL.isOutOfFlow(n) || RL.clips(n, 'x')) break;
      }
    }
  },
});

// ---------------------------------------------------------------------------
RL.rule({
  id: 'text-clipped',
  run(ctx) {
    const seen = new Set();
    for (const t of ctx.texts) {
      if (RL.isIgnored(t.el, 'text-clipped')) continue;
      const fs = fontSize(t.el);
      let passedAbs = false;
      for (let n = t.el, d = 0; n && n !== document.body && n !== document.documentElement && d < 40; n = RL.parentOf(n), d++) {
        const s = RL.cs(n);
        const isSvgRoot = n.namespaceURI === SVG_NS && n.tagName.toLowerCase() === 'svg';
        if (n.namespaceURI === SVG_NS && !isSvgRoot) continue;
        if (s.position === 'fixed') break;
        const doesClip = !(passedAbs && s.position === 'static' && s.transform === 'none');
        if (doesClip && (isSvgRoot ? s.overflow !== 'visible' : (RL.clips(n, 'x') || RL.clips(n, 'y')))) {
          const scrollX = !isSvgRoot && RL.isScrollContainer(n, 'x');
          const scrollY = !isSvgRoot && RL.isScrollContainer(n, 'y');
          if (scrollX && scrollY) break; // scrollable area: partially visible content is expected
          const box = isSvgRoot ? RL.rectOf(n) : paddingBox(n);
          if (box.w <= 2 || box.h <= 2) break;
          const inter = t.rects.some((r) => RL.intersect(r, box));
          if (!inter) break; // fully hidden (carousel slide, collapsed panel): not a defect
          const o = overflowBeyond(t.rects, box);
          const tolX = 2, tolY = Math.max(2, fs * 0.28);
          const cutX = !scrollX && (isSvgRoot || RL.clips(n, 'x')) && (o.left > tolX || o.right > tolX);
          const cutY = !scrollY && (isSvgRoot || RL.clips(n, 'y')) && (o.top > tolY || o.bottom > tolY);
          // one report per clipped HTML box, but every clipped label of an SVG chart
          const key = isSvgRoot ? t.el : n;
          if ((cutX || cutY) && !seen.has(key)) {
            if (cutX && !cutY && isIntentionalTruncation(t.el, n, 'x')) break;
            if (cutY && isIntentionalTruncation(t.el, n, 'y')) break;
            seen.add(key);
            ctx.report({
              rule: 'text-clipped', el: t.el, related: n === t.el ? undefined : n,
              message: 'Text is cut off by ' + (isSvgRoot ? 'the edge of its <svg>' : 'an overflow:' + (cutX ? s.overflowX : s.overflowY) + ' container') +
                ' (' + fmtOver(o, cutX ? tolX : 1e9, cutY ? tolY : 1e9) + ').',
              details: { overflow: o, clipper: isSvgRoot ? 'svg' : 'overflow' },
            });
          }
          break;
        }
        if (s.position === 'absolute') passedAbs = true;
        else if (s.position !== 'static' || s.transform !== 'none') passedAbs = false;
      }
    }
  },
});

// ---------------------------------------------------------------------------
const MEDIA = new Set(['img', 'video', 'canvas', 'svg', 'iframe', 'picture']);
const CONTROL = new Set(['button', 'input', 'select', 'textarea']);
const TABLE_PARTS = new Set(['col', 'colgroup', 'tr', 'td', 'th', 'thead', 'tbody', 'tfoot', 'caption']);
RL.isSolid = function (el) {
  const tag = el.tagName.toLowerCase();
  if (TABLE_PARTS.has(tag) || /^table-/.test(RL.cs(el).display)) return false; // table internals tile, never overlap
  if (MEDIA.has(tag) && (tag !== 'svg' || !(el.parentElement && el.parentElement.closest('svg')))) return true;
  if (CONTROL.has(tag)) return true;
  if (RL.isInline(el)) return false;
  return RL.hasVisibleBoundary(el);
};

RL.rule({
  id: 'content-overflow',
  run(ctx) {
    const seen = new Set();
    for (const el of ctx.elements) {
      if (!RL.isSolid(el) || !RL.isVisible(el) || RL.isOutOfFlow(el)) continue;
      if (el.namespaceURI === SVG_NS && el.tagName.toLowerCase() !== 'svg') continue;
      if (RL.cs(el).transform !== 'none') continue;
      if (RL.isIgnored(el, 'content-overflow')) continue;
      const er = RL.rectOf(el);
      if (er.w < 4 || er.h < 4) continue;
      for (let n = RL.parentOf(el), d = 0; n && n !== document.body && n !== document.documentElement && d < 30; n = RL.parentOf(n), d++) {
        if (RL.clips(n, 'x') || RL.clips(n, 'y')) {
          // A clipped control is unusable; clipped media/cards are usually intentional crops.
          if (RL.isInteractive(el) && !RL.isScrollContainer(n, 'x') && !RL.isScrollContainer(n, 'y') && !seen.has(n)) {
            const box = paddingBox(n);
            const o = overflowBeyond([er], box);
            if ((o.left > 2 || o.right > 2 || o.top > 2 || o.bottom > 2) && RL.intersect(er, box)) {
              seen.add(n);
              ctx.report({ rule: 'content-overflow', el, related: n, message: 'Interactive element is partially cut off by its overflow:hidden container (' + fmtOver(o, 2, 2) + ').', details: { overflow: o, clipped: true } });
            }
          }
          break;
        }
        const sides = RL.boundarySides(n);
        if (sides) {
          if (seen.has(n)) break;
          const o = overflowBeyond([er], paddingBox(n));
          for (const k of ['top', 'right', 'bottom', 'left']) if (!sides[k]) o[k] = 0; // past an edge that isn't drawn
          if (o.left > 2 || o.right > 2 || o.top > 2 || o.bottom > 2) {
            seen.add(n);
            ctx.report({ rule: 'content-overflow', el, related: n, message: 'Element sticks out of its container (' + fmtOver(o, 2, 2) + ').', details: { overflow: o } });
            break;
          }
          if (sides.x && sides.y) break;
        }
        if (RL.isOutOfFlow(n) || RL.cs(n).transform !== 'none') break;
      }
    }
  },
});

// ---------------------------------------------------------------------------
RL.rule({
  id: 'viewport-overflow',
  run(ctx) {
    const de = document.documentElement;
    const vw = de.clientWidth;
    const scrollW = Math.max(de.scrollWidth, document.body ? document.body.scrollWidth : 0);
    const hs = RL.cs(de), bs = RL.cs(document.body);
    const canScroll = !/hidden|clip/.test(hs.overflowX) && !/hidden|clip/.test(bs.overflowX);
    const scrolls = canScroll && scrollW > vw + 1;

    const culprit = new Map();
    for (const el of ctx.elements) {
      if (!RL.isVisible(el)) continue;
      const s = RL.cs(el);
      if (s.position === 'fixed') continue;
      if (el.namespaceURI === SVG_NS && el.tagName.toLowerCase() !== 'svg') continue;
      if (RL.isInline(el) && !el.firstElementChild && el.tagName !== 'IMG') { /* inline text handled via its block */ }
      const r = el.getBoundingClientRect();
      if (r.width === 0 || r.height === 0) continue;
      const over = Math.max(r.right + scrollX - vw, -(r.left + scrollX));
      if (over <= 1) continue;
      // fully off-screen (off-canvas menus) only matters if the page actually scrolls
      if ((r.left + scrollX >= vw || r.right + scrollX <= 0) && !scrolls) continue;
      let clipped = false;
      for (let n = RL.parentOf(el); n && n !== document.body && n !== de; n = RL.parentOf(n)) {
        if (RL.clips(n, 'x')) {
          const nr = n.getBoundingClientRect();
          if (nr.right + scrollX <= vw + 1 && nr.left + scrollX >= -1) { clipped = true; break; }
        }
        if (RL.cs(n).position === 'fixed') { clipped = true; break; }
      }
      if (clipped) continue;
      culprit.set(el, over);
    }
    // Text that runs past the viewport out of a box that fits (a long unbreakable word in a heading with
    // no border or background, so text-overflow has no box to measure against): the page scrolls sideways.
    // Only when it does: the visible parts of the text are already cut to every clipping ancestor.
    const textOnly = new Set();
    if (scrolls) {
      for (const t of ctx.texts) {
        if (culprit.has(t.el) || RL.flagged.has(t.el) || RL.isIgnored(t.el, 'viewport-overflow')) continue;
        const over = Math.max(...t.vis.map((r) => r.x + r.w)) - vw;
        if (over <= 1) continue;
        // in a fixed layer, or inside a box already reported as too wide
        let skip = false;
        for (let n = t.el; n && n !== document.body && n !== de && !skip; n = RL.parentOf(n)) skip = RL.cs(n).position === 'fixed' || (n !== t.el && culprit.has(n) && !textOnly.has(n));
        if (skip) continue;
        culprit.set(t.el, over);
        textOnly.add(t.el);
      }
    }
    // Keep only the outermost culprits (whose parent is not itself overflowing as much).
    const roots = [];
    for (const [el, over] of culprit) {
      const p = RL.parentOf(el);
      if (p && culprit.has(p) && culprit.get(p) >= over - 1) continue;
      if (RL.isIgnored(el, 'viewport-overflow')) continue;
      roots.push([el, over]);
    }
    roots.sort((a, b) => b[1] - a[1]);
    for (const [el, over] of roots.slice(0, 6)) {
      if (!scrolls) {
        // Page cannot scroll sideways: only content that gets cut off matters.
        const hasContent = (el.innerText || '').trim() || RL.isInteractive(el) || el.querySelector('img,svg,button,a,input');
        if (!hasContent) continue;
      }
      ctx.report({
        rule: 'viewport-overflow', el,
        message: textOnly.has(el)
          ? 'Text runs ' + Math.round(over) + 'px beyond the ' + vw + 'px viewport, causing horizontal page scroll (a long word or URL that does not wrap: overflow-wrap: anywhere).'
          : scrolls
          ? 'Element extends ' + Math.round(over) + 'px beyond the ' + vw + 'px viewport, causing horizontal page scroll.'
          : 'Element extends ' + Math.round(over) + 'px beyond the ' + vw + 'px viewport and is cut off (overflow-x is hidden on the page).',
        details: { overflow: Math.round(over), viewportWidth: vw, pageScrollWidth: scrollW, width: Math.round(el.getBoundingClientRect().width), cssWidth: RL.cs(el).width, minWidth: RL.cs(el).minWidth, whiteSpace: RL.cs(el).whiteSpace },
      });
    }
  },
});

// ---------------------------------------------------------------------------
RL.rule({
  id: 'accidental-scrollbar',
  run(ctx) {
    for (const el of ctx.elements) {
      const tag = el.tagName;
      if (tag === 'TEXTAREA' || tag === 'SELECT' || el === document.body) continue;
      const s = RL.cs(el);
      if (!/auto|scroll/.test(s.overflowX + s.overflowY)) continue;
      if (!RL.isVisible(el) || RL.isIgnored(el, 'accidental-scrollbar')) continue;
      for (const axis of ['y', 'x']) {
        const mode = axis === 'y' ? s.overflowY : s.overflowX;
        if (mode !== 'auto' && mode !== 'scroll') continue;
        const client = axis === 'y' ? el.clientHeight : el.clientWidth;
        const diff = axis === 'y' ? el.scrollHeight - el.clientHeight : el.scrollWidth - el.clientWidth;
        if (client < 16) continue;
        if (diff > 0 && diff <= 24) {
          ctx.report({
            rule: 'accidental-scrollbar', el, severity: diff <= 8 ? undefined : 'warn',
            message: 'Content overflows by only ' + diff + 'px on the ' + axis + ' axis, producing a scrollbar for a tiny amount of content.',
            details: { axis, overflow: diff, mode },
          });
          break;
        }
      }
    }
  },
});

// ---- rules/overlap.js
// Overlap rules: colliding text (incl. chart/diagram labels), colliding boxes,
// content hidden underneath other layers.

const CELL = 96;
function spatialPairs(items, rectsOf, cb) {
  const grid = new Map();
  items.forEach((it, i) => {
    for (const r of rectsOf(it)) {
      for (let cx = Math.floor(r.x / CELL); cx <= Math.floor(r.right / CELL); cx++) {
        for (let cy = Math.floor(r.y / CELL); cy <= Math.floor(r.bottom / CELL); cy++) {
          const k = cx + ':' + cy;
          let list = grid.get(k);
          if (!list) grid.set(k, (list = []));
          list.push([i, r]);
        }
      }
    }
  });
  const done = new Set();
  for (const list of grid.values()) {
    if (list.length < 2) continue;
    for (let a = 0; a < list.length; a++) {
      for (let b = a + 1; b < list.length; b++) {
        const [i, ri] = list[a], [j, rj] = list[b];
        if (i === j) continue;
        const key = i < j ? i + ',' + j : j + ',' + i;
        if (done.has(key)) continue;
        const inter = RL.intersect(ri, rj);
        if (!inter) continue;
        if (cb(items[i], items[j], ri, rj, inter) === true) done.add(key);
      }
    }
  }
}

// Is an opaque layer painted between two elements at a point? (=> lower one hidden)
function occludedBetween(stack, upperEl, lowerEl) {
  const iu = stack.findIndex((e) => e === upperEl || RL.containsComposed(upperEl, e));
  const il = stack.findIndex((e) => e === lowerEl || RL.containsComposed(lowerEl, e));
  if (iu === -1 || il === -1) return false;
  const [a, b] = iu < il ? [iu, il] : [il, iu];
  const lower = iu < il ? lowerEl : upperEl;
  // includes the upper element itself: an opaque box (tooltip, badge) hides what is under it
  for (let k = a; k < b; k++) {
    const e = stack[k];
    if (RL.containsComposed(e, lower)) continue; // ancestor of the lower element
    if (RL.isOpaqueLayer(e)) return true;
  }
  return false;
}

// ---------------------------------------------------------------------------
RL.rule({
  id: 'text-overlap',
  order: 90,
  run(ctx) {
    const texts = ctx.texts.filter((t) => !RL.isIgnored(t.el, 'text-overlap') && RL.effectiveOpacity(t.el) >= 0.3);
    const reported = new Set();
    spatialPairs(texts, (t) => t.vis, (a, b, ra, rb, inter) => {
      if (a.node === b.node) return;
      const minH = Math.min(ra.h, rb.h), minW = Math.min(ra.w, rb.w);
      if (inter.w <= 3 || inter.h < minH * 0.5 || inter.w < Math.min(minW * 0.15, 8)) return;
      const key = RL.selector(a.el) + '|' + RL.selector(b.el);
      if (reported.has(key)) return true;
      const { stack } = RL.stackAt(inter.x + inter.w / 2, inter.y + inter.h / 2);
      if (occludedBetween(stack, a.el, b.el)) return true;
      reported.add(key);
      const inSvg = a.el.namespaceURI === 'http://www.w3.org/2000/svg' || b.el.namespaceURI === 'http://www.w3.org/2000/svg';
      ctx.report({
        rule: 'text-overlap', el: a.el, related: b.el,
        message: (inSvg ? 'Chart/diagram labels collide: ' : 'Text overlaps other text: ') +
          '"' + RL.snippet(a.node, 30) + '" and "' + RL.snippet(b.node, 30) + '" overlap by ' + Math.round(inter.w) + '×' + Math.round(inter.h) + 'px.',
        details: { overlap: { w: Math.round(inter.w), h: Math.round(inter.h) }, svg: inSvg },
      });
      return true;
    });
  },
});

// ---------------------------------------------------------------------------
function chainUpTo(el, ancestor) {
  const out = [];
  for (let n = el; n && n !== ancestor; n = RL.parentOf(n)) out.push(n);
  return out;
}
function commonAncestor(a, b) {
  const set = new Set();
  for (let n = a; n; n = RL.parentOf(n)) set.add(n);
  for (let n = b; n; n = RL.parentOf(n)) if (set.has(n)) return n;
  return null;
}
function intentionalStacking(chain) {
  for (const n of chain) {
    const s = RL.cs(n);
    if (s.position === 'absolute' || s.position === 'fixed' || s.position === 'sticky') return 'positioned';
    if (s.transform !== 'none' || s.translate !== 'none' || s.rotate !== 'none' || s.scale !== 'none') return 'transform';
    if (parseFloat(s.marginTop) < 0 || parseFloat(s.marginLeft) < 0 || parseFloat(s.marginRight) < 0 || parseFloat(s.marginBottom) < 0) return 'negative-margin';
    if (s.float !== 'none') return 'float';
    if (s.position === 'relative' && ((parseFloat(s.top) || 0) !== 0 || (parseFloat(s.left) || 0) !== 0 || (parseFloat(s.bottom) || 0) !== 0)) return 'offset';
    const p = RL.parentOf(n);
    if (p && /grid/.test(RL.cs(p).display) && (s.gridRowStart !== 'auto' || s.gridColumnStart !== 'auto')) return 'grid-placement';
  }
  return null;
}

function isAdornment(field, el) {
  if (!RL.isTextField(field)) return false;
  const f = field.getBoundingClientRect(), r = el.getBoundingClientRect();
  return r.left >= f.left - 1 && r.right <= f.right + 1 && r.top >= f.top - 1 && r.bottom <= f.bottom + 1;
}

RL.rule({
  id: 'element-overlap',
  order: 91,
  run(ctx) {
    let solids = ctx.elements.filter((el) => {
      if (el === document.body || el === document.documentElement) return false;
      if (!RL.isSolid(el) || !RL.isVisible(el)) return false;
      if (el.namespaceURI === 'http://www.w3.org/2000/svg' && el.tagName.toLowerCase() !== 'svg') return false;
      const r = el.getBoundingClientRect();
      return r.width >= 8 && r.height >= 8 && !RL.isIgnored(el, 'element-overlap');
    });
    // Only the visible part of each box counts: content scrolled/clipped out of view can't overlap anything.
    const rects = new Map();
    for (const el of solids) {
      const clip = RL.clipBoxOf(RL.parentOf(el));
      const r = clip ? RL.intersect(RL.rectOf(el), clip) : RL.rectOf(el);
      if (r && r.w >= 4 && r.h >= 4) rects.set(el, r);
    }
    solids = solids.filter((el) => rects.has(el));
    const reported = [];
    spatialPairs(solids, (el) => [rects.get(el)], (a, b, ra, rb, inter) => {
      if (RL.containsComposed(a, b) || RL.containsComposed(b, a)) return true;
      if (inter.w <= 3 || inter.h <= 3) return true;
      const ca = commonAncestor(a, b);
      const why = intentionalStacking(chainUpTo(a, ca)) || intentionalStacking(chainUpTo(b, ca));
      if (why && !(why === 'positioned' && RL.isInteractive(a) && RL.isInteractive(b))) return true;
      // A positioned button inside a text field's box (show-password, clear) is an adornment;
      // if it covers the text area, input-icon-overlap reports that.
      if (why === 'positioned' && (isAdornment(a, b) || isAdornment(b, a))) return true;
      if (reported.some(([x, y]) => (RL.containsComposed(x, a) && RL.containsComposed(y, b)) || (RL.containsComposed(x, b) && RL.containsComposed(y, a)))) return true;
      reported.push([a, b]);
      ctx.report({
        rule: 'element-overlap', el: a, related: b,
        message: 'Element overlaps a neighbouring element by ' + Math.round(inter.w) + '×' + Math.round(inter.h) + 'px.',
        details: { overlap: { w: Math.round(inter.w), h: Math.round(inter.h) } },
      });
      return true;
    });
  },
});

// ---------------------------------------------------------------------------
RL.rule({
  id: 'obscured-content',
  order: 92,
  run(ctx) {
    const targets = [];
    const seenEl = new Set();
    for (const t of ctx.texts) {
      if (seenEl.has(t.el)) continue;
      seenEl.add(t.el);
      const r = t.vis[0];
      targets.push({ el: t.el, x: r.x + r.w / 2, y: r.y + r.h / 2, kind: 'text' });
    }
    for (const el of ctx.elements) {
      if (!RL.isInteractive(el) || seenEl.has(el) || !RL.isVisible(el)) continue;
      const clip = RL.clipBoxOf(RL.parentOf(el));
      const r = clip ? RL.intersect(RL.rectOf(el), clip) : RL.rectOf(el);
      if (!r || r.w < 2 || r.h < 2) continue;
      targets.push({ el, x: r.x + r.w / 2, y: r.y + r.h / 2, kind: 'control' });
    }
    targets.sort((a, b) => a.y - b.y);
    const vpArea = innerWidth * innerHeight;
    const reported = new Set();
    let checks = 0;
    for (const tg of targets) {
      if (checks++ > 2500) break;
      if (RL.isIgnored(tg.el, 'obscured-content')) continue;
      const { stack, scrolled } = RL.stackAt(tg.x, tg.y);
      const idx = stack.findIndex((e) => e === tg.el || RL.containsComposed(tg.el, e));
      if (idx <= 0) continue;
      for (let k = 0; k < idx; k++) {
        const e = stack[k];
        if (RL.containsComposed(e, tg.el) || RL.containsComposed(tg.el, e)) continue;
        if (RL.isDevTool(e) || (e.closest && e.closest('nextjs-portal,vite-error-overlay,astro-dev-toolbar'))) continue;
        if (!RL.isOpaqueLayer(e)) continue;
        if (RL.isIgnored(e, 'obscured-content')) break;
        // Layered illustrations / mockups (stacked absolutely positioned or transformed cards) are deliberate.
        if (RL.layeredBetween(tg.el, RL.commonAncestor(tg.el, e))) break;
        const fixed = RL.fixedAncestor(e);
        const tgFixed = RL.fixedAncestor(tg.el);
        if (fixed && !tgFixed && scrolled) break; // header over content only because we scrolled
        if (fixed) {
          const fr = fixed.getBoundingClientRect();
          if (fr.width * fr.height > vpArea * 0.5) break; // modal / backdrop
        }
        const key = RL.selector(e) + '>' + RL.selector(RL.nearestBlock(tg.el));
        if (reported.has(key)) break;
        reported.add(key);
        ctx.report({
          rule: 'obscured-content', el: tg.el, related: e,
          message: (tg.kind === 'control' ? 'Interactive element' : 'Text') + ' is hidden underneath another element' + (fixed ? ' (a fixed/sticky layer)' : '') + '.',
          details: { kind: tg.kind, coveredBy: e.tagName.toLowerCase() },
        });
        break;
      }
    }
  },
});

// ---- rules/content.js
// renderlint-ignore-file (describes placeholder/emoji rules, so it mentions their trigger words)
// Content rules: emoji, leaked placeholders, broken / distorted images,
// dead links, invalid nesting, missing viewport meta.

RL.rule({
  id: 'emoji',
  run(ctx) {
    const seen = new Set();
    const hit = (el, chars, where) => {
      if (seen.has(el) || RL.isIgnored(el, 'emoji')) return;
      seen.add(el);
      const uniq = Array.from(new Set(chars)).slice(0, 6).join(' ');
      ctx.report({
        rule: 'emoji', el,
        message: 'Emoji used in the UI' + (where ? ' (' + where + ')' : '') + ': ' + uniq + '. Use an icon from an icon set (SVG) instead.',
        details: { emoji: Array.from(new Set(chars)) },
      });
    };
    for (const t of ctx.texts) {
      const m = t.text.match(RL.EMOJI_RE);
      if (m) hit(t.el, m);
    }
    for (const el of ctx.elements) {
      for (const pseudo of ['::before', '::after']) {
        const c = getComputedStyle(el, pseudo).content;
        if (!c || c === 'none' || c === 'normal' || c.length < 3) continue;
        const m = c.match(RL.EMOJI_RE);
        if (m && RL.isVisible(el)) hit(el, m, pseudo + ' content');
      }
      const tag = el.tagName;
      if ((tag === 'INPUT' || tag === 'TEXTAREA') && RL.isVisible(el)) {
        const m = ((el.value || '') + ' ' + (el.placeholder || '')).match(RL.EMOJI_RE);
        if (m) hit(el, m, 'input text');
      }
    }
  },
});

// ---------------------------------------------------------------------------
const LEAK_PATTERNS = [
  [/\[object (Object|Promise|Array)\]/, 'error', 'a stringified JavaScript object'],
  [/^(undefined|null|NaN|Infinity|-Infinity)$/, 'error', 'a raw JavaScript value'],
  [/(^|[\s$€£¥(])(undefined|NaN)(?=$|[\s%).,!?:])/, 'error', 'a raw JavaScript value'],
  [/\bInvalid Date\b/, 'error', '"Invalid Date"'],
  [/\{\{\s*[\w.$[\]'"]+\s*\}\}|\$\{\s*[\w.$]+\s*\}/, 'error', 'an unrendered template expression'],
  [/\blorem ipsum\b|\bdolor sit amet\b/i, 'warn', 'placeholder "lorem ipsum" copy'],
  [/^(TODO|FIXME|TBD|XXX)\b|\b(TODO|FIXME):/, 'warn', 'a TODO/FIXME note'],
  [/\b(Your|Company|Product|Brand) (Name|Logo) Here\b|^(Image|Logo|Title|Heading|Placeholder)( \d+)?$/i, 'warn', 'placeholder copy'],
];

// WordPress sample content and Elementor's default widget texts, left on a published page.
// Only checked on WordPress/Elementor pages, and the generic ones only inside the widget they come from.
const WP_DEFAULTS = [
  [/^Just another WordPress site$/, null, 'the default WordPress tagline'],
  [/^Hello world!$|^Welcome to WordPress\. This is your first post\.|^This is an example page\.|^Sample Page$|^A WordPress Commenter$|^Hi, this is a comment\./, null, 'WordPress sample content'],
  [/^Add Your Heading Text Here$|^I am a description\. Click the edit button to change this text\.$|Click edit button to change this text/, null, 'Elementor\'s default widget text'],
  [/^This is the heading$/, '.elementor-widget-icon-box,.elementor-widget-image-box', 'Elementor\'s default widget text'],
  [/^Cool Number$/, '.elementor-widget-counter', 'Elementor\'s default widget text'],
  [/^(My Skill|Web Designer)$/, '.elementor-widget-progress', 'Elementor\'s default widget text'],
  [/^This is an Alert$/, '.elementor-widget-alert', 'Elementor\'s default widget text'],
  [/^List Item #\d+$/, '.elementor-widget-icon-list', 'Elementor\'s default widget text'],
  [/^(Tab|Accordion|Toggle) #\d+$/, '.elementor-widget-tabs,.elementor-widget-accordion,.elementor-widget-toggle,.elementor-widget-n-tabs,.elementor-widget-n-accordion', 'Elementor\'s default widget text'],
  [/^(John Doe|Designer)$/, '.elementor-widget-testimonial', 'Elementor\'s default widget text'],
  [/^Click here$/, '.elementor-widget-button', 'Elementor\'s default button text'],
];

RL.rule({
  id: 'placeholder-text',
  run(ctx) {
    const seen = new Set();
    const wp = RL.platform();
    for (const t of ctx.texts) {
      if (seen.has(t.el) || RL.isIgnored(t.el, 'placeholder-text')) continue;
      const tag = t.el.tagName;
      if (tag === 'CODE' || tag === 'PRE' || tag === 'KBD' || tag === 'SAMP' || t.el.closest('pre,code,kbd,samp,[contenteditable]')) continue;
      for (const [re, sev, what] of LEAK_PATTERNS) {
        if (re.test(t.text)) {
          seen.add(t.el);
          ctx.report({ rule: 'placeholder-text', el: t.el, severity: sev, message: 'Visible text contains ' + what + ': "' + RL.snippet(t.node, 50) + '".' });
          break;
        }
      }
      if (seen.has(t.el) || !(wp.wordpress || wp.elementor)) continue;
      const full = (t.el.textContent || '').replace(/\s+/g, ' ').trim();
      for (const [re, scope, what] of WP_DEFAULTS) {
        if (re.test(full) && (!scope || t.el.closest(scope))) {
          seen.add(t.el);
          ctx.report({ rule: 'placeholder-text', el: t.el, severity: 'warn', message: 'Visible text is ' + what + ', never replaced: "' + RL.snippet(t.el, 50) + '".', details: { wordpress: true } });
          break;
        }
      }
    }
  },
});

// ---------------------------------------------------------------------------
RL.rule({
  id: 'broken-image',
  run(ctx) {
    for (const el of ctx.elements) {
      if (el.tagName !== 'IMG' || !RL.isVisible(el) || RL.isIgnored(el, 'broken-image')) continue;
      const src = el.currentSrc || el.getAttribute('src') || '';
      if (!src && !el.getAttribute('srcset')) {
        ctx.report({ rule: 'broken-image', el, message: '<img> has no src.' });
      } else if (el.complete && el.naturalWidth === 0) {
        ctx.report({ rule: 'broken-image', el, message: 'Image failed to load: ' + src.slice(0, 120), details: { src } });
      }
    }
  },
});

RL.rule({
  id: 'image-distortion',
  run(ctx) {
    for (const el of ctx.elements) {
      if (el.tagName !== 'IMG' || !RL.isVisible(el) || !el.naturalWidth || !el.naturalHeight) continue;
      if (RL.isIgnored(el, 'image-distortion')) continue;
      const src = el.currentSrc || el.src || '';
      if (/\.svg(\?|#|$)|^data:image\/svg/i.test(src)) continue;
      const s = RL.cs(el);
      if (s.objectFit && s.objectFit !== 'fill') continue;
      const pl = parseFloat(s.paddingLeft) + parseFloat(s.paddingRight) + parseFloat(s.borderLeftWidth) + parseFloat(s.borderRightWidth);
      const pt = parseFloat(s.paddingTop) + parseFloat(s.paddingBottom) + parseFloat(s.borderTopWidth) + parseFloat(s.borderBottomWidth);
      const r = el.getBoundingClientRect();
      const w = r.width - pl, h = r.height - pt;
      if (w < 16 || h < 16) continue;
      const natural = el.naturalWidth / el.naturalHeight;
      const rendered = w / h;
      const diff = Math.abs(rendered - natural) / natural;
      if (diff > 0.06) {
        ctx.report({
          rule: 'image-distortion', el,
          message: 'Image is ' + (rendered > natural ? 'stretched horizontally' : 'squashed horizontally') + ' (' + Math.round(diff * 100) + '% off its natural aspect ratio ' + el.naturalWidth + '×' + el.naturalHeight + ', rendered ' + Math.round(w) + '×' + Math.round(h) + ').',
          details: { natural: [el.naturalWidth, el.naturalHeight], rendered: [Math.round(w), Math.round(h)] },
        });
      }
    }
  },
});

RL.rule({
  id: 'missing-alt',
  run(ctx) {
    for (const el of ctx.elements) {
      if (el.tagName !== 'IMG' || el.hasAttribute('alt') || el.getAttribute('role') === 'presentation' || el.getAttribute('aria-hidden') === 'true') continue;
      if (!RL.isVisible(el) || RL.isIgnored(el, 'missing-alt')) continue;
      if (el.hasAttribute('aria-label') || el.hasAttribute('aria-labelledby')) continue;
      ctx.report({ rule: 'missing-alt', el, message: '<img> has no alt attribute (use alt="" for decorative images).' });
    }
  },
});

// ---------------------------------------------------------------------------
function hasClickHandler(el) {
  for (let n = el, d = 0; n && d < 3; n = n.parentElement, d++) {
    if (n.onclick || n.hasAttribute('onclick') || n.hasAttribute('@click') || n.hasAttribute('v-on:click') || n.hasAttribute('x-on:click') || n.hasAttribute('hx-get') || n.hasAttribute('hx-post') || n.hasAttribute('data-action')) return true;
    for (const k of Object.keys(n)) {
      if (k.startsWith('__reactProps$') && n[k] && (n[k].onClick || n[k].onMouseDown || n[k].onPointerDown)) return true;
      if (k === '_vei' && n[k] && Object.keys(n[k]).some((e) => /click|mousedown|pointerdown/i.test(e))) return true;
      if (/^__(click|mousedown|pointerdown)$/.test(k)) return true; // svelte 5 delegated events
      if (k.startsWith('jQuery') || k === '__zone_symbol__clickfalse') return true;
    }
  }
  return false;
}
RL.hasClickHandler = hasClickHandler;

// Bootstrap 4/5 and similar toggles: one delegated handler on document serves every
// [data-toggle] link, so no listener on the link proves it is live. A toggle whose target
// exists on the page (data-target, data-bs-target, aria-controls, or the dropdown menu next to it) is.
function togglesTarget(el) {
  const toggle = el.getAttribute('data-bs-toggle') || el.getAttribute('data-toggle');
  if (!toggle) return false;
  for (const attr of ['data-bs-target', 'data-target']) {
    const sel = el.getAttribute(attr);
    if (!sel) continue;
    try { if (document.querySelector(sel)) return true; } catch (e) { /* not a selector */ }
  }
  const ids = (el.getAttribute('aria-controls') || '').split(/\s+/).filter(Boolean);
  if (ids.some((id) => document.getElementById(id))) return true;
  if (/^dropdown$/i.test(toggle) && el.parentElement && el.parentElement.querySelector(':scope > .dropdown-menu')) return true;
  return false;
}

RL.rule({
  id: 'dead-link',
  run(ctx) {
    for (const el of ctx.elements) {
      if (el.tagName !== 'A' || !RL.isVisible(el) || RL.isIgnored(el, 'dead-link')) continue;
      const href = el.getAttribute('href');
      const dead = href === null ? !el.hasAttribute('name') && !el.id && RL.cs(el).cursor === 'pointer'
        : href.trim() === '' || href.trim() === '#' || /^javascript:\s*(void\(0\)|;)?\s*;?$/i.test(href.trim());
      if (!dead || hasClickHandler(el) || togglesTarget(el) || el.getAttribute('role') === 'button' && hasClickHandler(el)) continue;
      ctx.report({
        rule: 'dead-link', el, needsListenerCheck: true,
        message: 'Link goes nowhere (href=' + JSON.stringify(href) + ') and has no click handler.',
      });
    }
  },
});

RL.rule({
  id: 'nested-interactive',
  run(ctx) {
    for (const el of ctx.elements) {
      const tag = el.tagName;
      if (!(tag === 'A' && el.hasAttribute('href')) && tag !== 'BUTTON') continue;
      if (RL.isIgnored(el, 'nested-interactive')) continue;
      const parent = el.parentElement && el.parentElement.closest('a[href],button');
      if (parent) {
        ctx.report({ rule: 'nested-interactive', el, related: parent, message: '<' + tag.toLowerCase() + '> is nested inside <' + parent.tagName.toLowerCase() + '>; interactive elements cannot contain each other (invalid HTML, causes hydration errors and broken clicks).' });
      }
    }
  },
});

RL.rule({
  id: 'missing-viewport-meta',
  run(ctx) {
    if (document.querySelector('meta[name="viewport" i]')) return;
    if (RL.isIgnored(document.body, 'missing-viewport-meta')) return;
    ctx.report({ rule: 'missing-viewport-meta', el: document.body, message: 'No <meta name="viewport"> tag: phones will render the page at desktop width and zoom out.' });
  },
});

RL.rule({
  id: 'oversized-icon',
  run(ctx) {
    for (const el of ctx.elements) {
      if (el.tagName.toLowerCase() !== 'svg' || (el.parentElement && el.parentElement.closest('svg'))) continue;
      const vb = el.viewBox && el.viewBox.baseVal;
      if (!vb || !vb.width || !vb.height || Math.max(vb.width, vb.height) > 48) continue; // only icon-sized artwork
      if (!RL.isVisible(el) || RL.isIgnored(el, 'oversized-icon')) continue;
      if (el.hasAttribute('width') || el.hasAttribute('height')) continue;
      const r = el.getBoundingClientRect();
      // An unsized icon stretches to its container (or its flex share); a deliberately large icon (e.g. size-28) has a CSS size.
      let unsized;
      const map = el.computedStyleMap && el.computedStyleMap();
      if (map) unsized = String(map.get('width')) === 'auto' && String(map.get('height')) === 'auto';
      else {
        const p = el.parentElement;
        const pw = p ? RL.paddingBox(p).w - (parseFloat(RL.cs(p).paddingLeft) || 0) - (parseFloat(RL.cs(p).paddingRight) || 0) : 0;
        unsized = pw > 0 && r.width >= pw * 0.9;
      }
      if (unsized && r.width >= 4 * vb.width && r.width > 96 && r.height > 64) {
        ctx.report({ rule: 'oversized-icon', el, message: 'A ' + vb.width + '×' + vb.height + ' icon is rendered at ' + Math.round(r.width) + '×' + Math.round(r.height) + 'px — it has no size, so it stretches to fill its container.', details: { viewBox: [vb.width, vb.height], rendered: [Math.round(r.width), Math.round(r.height)] } });
      }
    }
  },
});

RL.rule({
  id: 'broken-resource',
  run(ctx) {
    if (!document.fonts) return;
    const failed = new Set();
    // "X Fallback" faces (next/font, fontaine) point at local() system fonts that may not exist here.
    document.fonts.forEach((f) => { const fam = f.family.replace(/["']/g, ''); if (f.status === 'error' && !/fallback/i.test(fam)) failed.add(fam); });
    for (const family of failed) {
      ctx.report({ rule: 'broken-resource', el: document.body, message: 'Web font "' + family + '" failed to load; text falls back to a different font.', details: { font: family } });
    }
  },
});

// In-flow content that is still invisible after the page was scrolled through
// and animations finished: typically a scroll-reveal that never fires
// (IntersectionObserver threshold too high for tall sections on phones, or the
// reveal script delayed or broken, as with WordPress optimisation plugins).
// Reveal libraries hide with opacity (AOS, Framer Motion, GSAP) or with
// visibility (Elementor entrance animations, WOW.js, ScrollReveal).
const REVEAL_HIDDEN = '.elementor-invisible, .wow, [data-sr-id]';
RL.rule({
  id: 'invisible-content',
  run(ctx) {
    const reported = [];
    const vw = document.documentElement.clientWidth;
    for (const el of ctx.elements) {
      const s = RL.cs(el);
      if (s.position === 'absolute' || s.position === 'fixed' || s.display === 'none') continue;
      const hiddenByVisibility = s.visibility === 'hidden';
      if (!hiddenByVisibility && parseFloat(s.opacity) > 0.05) continue;
      if (reported.some((r) => r.contains(el))) continue;
      const p = RL.parentOf(el);
      if (hiddenByVisibility) {
        // Report the outermost hidden element only, and only when it takes up room on the page.
        if (p && p !== document.body && RL.cs(p).visibility === 'hidden') continue;
        if (el.closest('[aria-hidden="true"],[inert],details:not([open]),[role="menu"],[role="dialog"],[role="tabpanel"],[role="listbox"],[role="tooltip"],nav')) continue;
      } else if (p && p !== document.body && RL.effectiveOpacity(p) <= 0.05) continue; // report the outermost one only
      const text = (el.textContent || '').replace(/\s+/g, ' ').trim();
      if (text.length < 20 || el.getAttribute('aria-hidden') === 'true' || el.hasAttribute('inert')) continue;
      const r = el.getBoundingClientRect();
      if (r.width < 40 || r.height < 16) continue;
      if (hiddenByVisibility) {
        const reveal = el.matches(REVEAL_HIDDEN);
        // Without a reveal class: only a large block that leaves a blank gap, with nothing inside made visible again.
        if (!reveal && (r.height < 120 || r.width < vw * 0.3 || text.length < 40)) continue;
        if (Array.from(el.querySelectorAll('*')).some((d) => RL.cs(d).visibility === 'visible' && d.getBoundingClientRect().width > 0)) continue;
      }
      if (RL.isIgnored(el, 'invisible-content')) continue;
      // stacked slides/tabs: a visible sibling occupies the same box
      const sib = p ? Array.from(p.children).find((c) => c !== el && parseFloat(RL.cs(c).opacity) > 0.5 && RL.cs(c).visibility !== 'hidden' && (() => { const i = RL.intersect(RL.rectOf(c), RL.rectOf(el)); return i && i.w * i.h > 0.5 * r.width * r.height; })()) : null;
      if (sib) continue;
      reported.push(el);
      if (hiddenByVisibility) {
        const elementor = el.classList.contains('elementor-invisible');
        ctx.report({ rule: 'invisible-content', el, message: 'Content stays invisible (visibility: hidden' + (elementor ? ', class elementor-invisible' : '') + ') even after scrolling through the page, leaving a blank gap — ' +
          (elementor ? 'its Elementor entrance animation never ran (Elementor\'s script delayed or deferred by an optimisation plugin, a JavaScript error, or an animation the element doesn\'t support)?' : 'a reveal animation that never triggers?'), details: { visibility: 'hidden', elementor } });
      } else {
        ctx.report({ rule: 'invisible-content', el, message: 'Content stays invisible (opacity: ' + s.opacity + ') even after scrolling through the page — a reveal animation that never triggers?', details: { opacity: s.opacity } });
      }
    }
  },
});

// ---- rules/a11y.js
// Readability / usability rules: tap targets, tiny text, unlabeled controls,
// wrapping button labels, overly long lines, contrast (DOM approximation),
// focus indicators.

function isTextInline(el) {
  // An inline link inside a run of text (WCAG target-size exception).
  if (!RL.isInline(el)) return false;
  const block = RL.nearestBlock(el);
  const all = (block.innerText || '').trim().length;
  const own = (el.innerText || '').trim().length;
  return all > own + 10;
}

function distToRect(x, y, r) {
  const dx = Math.max(r.x - x, 0, x - r.right), dy = Math.max(r.y - y, 0, y - r.bottom);
  return Math.hypot(dx, dy);
}

RL.rule({
  id: 'tap-target',
  run(ctx) {
    const min = RL.options.minTapTarget || 24;
    const targets = ctx.elements.filter((el) => RL.isInteractive(el) && RL.isVisible(el)).map((el) => ({ el, r: RL.rectOf(el) })).filter((t) => t.r.w >= 1 && t.r.h >= 1);
    for (const t of targets) {
      const { el, r } = t;
      if (RL.isDisabled(el) || RL.isIgnored(el, 'tap-target')) continue;
      if (r.w >= min && r.h >= min) continue;
      const tag = el.tagName;
      if ((tag === 'INPUT' && /^(checkbox|radio)$/.test(el.type)) && (el.labels && el.labels.length)) continue;
      if (isTextInline(el)) continue;
      // The real target may be a larger interactive ancestor or a wrapping label
      const host = el.parentElement && el.parentElement.closest('a[href],button,label,[role=button]');
      if (host && host !== el) {
        const hr = host.getBoundingClientRect();
        if (hr.width >= min && hr.height >= min) continue;
      }
      // WCAG 2.5.8 spacing exception: a 24px circle around the target touches no other target.
      const cx = r.x + r.w / 2, cy = r.y + r.h / 2;
      const crowded = targets.some((u) => {
        if (u === t || RL.containsComposed(u.el, el) || RL.containsComposed(el, u.el)) return false;
        const undersized = u.r.w < min || u.r.h < min;
        if (undersized) return Math.hypot(cx - (u.r.x + u.r.w / 2), cy - (u.r.y + u.r.h / 2)) < min;
        return distToRect(cx, cy, u.r) < min / 2;
      });
      if (!crowded) continue;
      ctx.report({ rule: 'tap-target', el, message: 'Touch target is ' + Math.round(r.w) + '×' + Math.round(r.h) + 'px and crowded by neighbouring targets; make it at least ' + min + '×' + min + 'px (44×44 recommended) or space it out.', details: { w: Math.round(r.w), h: Math.round(r.h) } });
    }
  },
});

RL.rule({
  id: 'font-size-min',
  run(ctx) {
    const min = RL.options.minFontSize || 12;
    const seen = new Set();
    for (const t of ctx.texts) {
      const block = RL.nearestBlock(t.el);
      if (seen.has(block)) continue;
      if (t.el.closest('sup,sub') || t.el.namespaceURI === 'http://www.w3.org/2000/svg') continue;
      const fs = parseFloat(RL.cs(t.el).fontSize);
      if (fs < min && t.text.length > 1 && !RL.isIgnored(t.el, 'font-size-min')) {
        seen.add(block);
        ctx.report({ rule: 'font-size-min', el: t.el, message: 'Text is ' + fs + 'px; minimum readable size is ' + min + 'px.', details: { fontSize: fs } });
      }
    }
  },
});

// ---------------------------------------------------------------------------
function accessibleName(el) {
  const aria = el.getAttribute('aria-label');
  if (aria && aria.trim()) return aria.trim();
  const lb = el.getAttribute('aria-labelledby');
  if (lb) {
    const t = lb.split(/\s+/).map((id) => document.getElementById(id)).filter(Boolean).map((n) => n.textContent).join(' ').trim();
    if (t) return t;
  }
  if (el.labels && el.labels.length) {
    const t = Array.from(el.labels).map((l) => l.textContent).join(' ').trim();
    if (t) return t;
  }
  const text = (el.innerText || el.textContent || '').trim();
  if (text) return text;
  const img = el.querySelector('img[alt]:not([alt=""]), svg title, [aria-label]');
  if (img) return img.getAttribute('alt') || img.getAttribute('aria-label') || img.textContent;
  if (el.title && el.title.trim()) return el.title.trim();
  if (el.tagName === 'INPUT' && /^(submit|reset|button)$/.test(el.type)) return el.value || el.type;
  if (el.tagName === 'INPUT' && el.type === 'image') return el.alt;
  return '';
}

RL.rule({
  id: 'unlabeled-control',
  run(ctx) {
    for (const el of ctx.elements) {
      const tag = el.tagName;
      const isInput = (tag === 'INPUT' && !/^(hidden|submit|reset|button|image)$/.test(el.type)) || tag === 'SELECT' || tag === 'TEXTAREA';
      const isBtn = tag === 'BUTTON' || (tag === 'A' && el.hasAttribute('href')) || el.getAttribute('role') === 'button';
      if (!isInput && !isBtn) continue;
      if (!RL.isVisible(el) || RL.isIgnored(el, 'unlabeled-control')) continue;
      if (accessibleName(el)) continue;
      if (isInput && el.placeholder) {
        ctx.report({ rule: 'unlabeled-control', el, severity: 'warn', message: 'Form field has only a placeholder ("' + el.placeholder.slice(0, 40) + '") and no label; the hint disappears while typing and screen readers may skip it.' });
        continue;
      }
      ctx.report({ rule: 'unlabeled-control', el, message: (isInput ? 'Form field' : 'Icon-only ' + (tag === 'A' ? 'link' : 'button')) + ' has no accessible name. Add aria-label (or a visible label).' });
    }
  },
});

// ---------------------------------------------------------------------------
function looksLikeButton(el) {
  const tag = el.tagName;
  if (tag === 'BUTTON' || el.getAttribute('role') === 'button') return true;
  if (tag === 'A' && !RL.isInline(el) && RL.hasVisibleBoundary(el)) return true;
  return false;
}

RL.rule({
  id: 'button-text-wrap',
  run(ctx) {
    const seen = new Set();
    for (const t of ctx.texts) {
      const btn = t.el.closest('button,a,[role=button]');
      if (!btn || seen.has(btn) || !looksLikeButton(btn) || RL.isIgnored(btn, 'button-text-wrap')) continue;
      const label = (btn.innerText || '').trim();
      if (!label || label.length > 40 || label.split(/\s+/).length < 2) continue;
      const lines = new Set();
      const range = document.createRange();
      range.selectNodeContents(btn);
      for (const r of range.getClientRects()) if (r.width > 1 && r.height > 1) lines.add(Math.round(r.top / 4));
      // merge tops that are within one line-height
      const tops = Array.from(lines).sort((a, b) => a - b);
      let count = tops.length ? 1 : 0;
      const lh = (parseFloat(RL.cs(t.el).fontSize) || 16) / 4;
      for (let i = 1; i < tops.length; i++) if (tops[i] - tops[i - 1] > lh * 0.8) count++;
      seen.add(btn);
      if (count > 1) {
        ctx.report({ rule: 'button-text-wrap', el: btn, message: 'Button label "' + label.slice(0, 40) + '" wraps onto ' + count + ' lines.', details: { lines: count } });
      }
    }
  },
});

RL.rule({
  id: 'line-length',
  run(ctx) {
    const max = RL.options.maxLineLength || 120;
    for (const el of ctx.elements) {
      if (!/^(P|LI|BLOCKQUOTE|DD)$/.test(el.tagName) || !RL.isVisible(el) || RL.isIgnored(el, 'line-length')) continue;
      const text = (el.innerText || '').replace(/\s+/g, ' ').trim();
      if (text.length < max * 2) continue;
      const range = document.createRange();
      range.selectNodeContents(el);
      const tops = new Set();
      for (const r of range.getClientRects()) if (r.width > 1) tops.add(Math.round(r.top));
      const lines = Math.max(1, tops.size);
      const perLine = Math.round(text.length / lines);
      if (lines >= 3 && perLine > max) {
        ctx.report({ rule: 'line-length', el, message: 'Lines average ~' + perLine + ' characters; keep body text under ~' + max + ' (ideally 60–80) for readability.', details: { charsPerLine: perLine } });
      }
    }
  },
});

// ---------------------------------------------------------------------------
// Contrast. The Node runner measures contrast from real screenshots (handles
// gradients, images, overlays). In the browser-only client we approximate
// using the DOM background chain.

RL.contrastCandidates = function (texts) {
  const out = [];
  const seen = new Map();
  for (const t of texts) {
    if (RL.isIgnored(t.el, 'contrast')) continue;
    if (RL.isDisabled(t.el)) continue;
    // Text already reported as overflowing/obscured: its contrast is a symptom, not a separate defect.
    if (RL.flagged && RL.flagged.has(t.el)) continue;
    const s = RL.cs(t.el);
    const fs = parseFloat(s.fontSize) || 16;
    const weight = parseInt(s.fontWeight, 10) || 400;
    const large = fs >= 24 || (fs >= 18.66 && weight >= 700);
    const fill = s.webkitTextFillColor && s.webkitTextFillColor !== s.color ? s.webkitTextFillColor : s.color;
    let color = RL.parseColor(fill);
    const clipText = /text/.test(s.backgroundClip || '') || /text/.test(s.webkitBackgroundClip || '');
    let complex = false;
    if (t.el.namespaceURI === 'http://www.w3.org/2000/svg') {
      const f = RL.parseColor(s.fill);
      if (f) color = f;
      if (s.fill && /url\(/.test(s.fill)) complex = true;
    }
    if (clipText) complex = true;
    // masks, clip-paths, blend modes and filters change the painted color: measure real pixels
    let faded = false;
    for (let n = t.el, d = 0; n && n !== document.body && d < 25 && !faded; n = RL.parentOf(n), d++) {
      const ns = RL.cs(n);
      const mask = ns.maskImage && ns.maskImage !== 'none' ? ns.maskImage : ns.webkitMaskImage;
      // a gradient fade mask (e.g. "more content →" edge of a scroller) fades text on purpose
      if (mask && mask !== 'none' && /gradient/.test(mask) && /transparent|rgba\([^)]*,\s*0\)|\/\s*0\)/.test(mask)) faded = true;
    }
    if (faded) continue;
    for (let n = t.el, d = 0; n && n !== document.body && d < 12 && !complex; n = RL.parentOf(n), d++) {
      const ns = RL.cs(n);
      if ((ns.maskImage && ns.maskImage !== 'none') || (ns.webkitMaskImage && ns.webkitMaskImage !== 'none') ||
        (ns.clipPath && ns.clipPath !== 'none') || (ns.mixBlendMode && ns.mixBlendMode !== 'normal') || (ns.filter && ns.filter !== 'none')) complex = true;
    }
    const key = t.el;
    let entry = seen.get(key);
    if (!entry) {
      entry = { idx: out.length, el: t.el, rects: [], color, opacity: RL.effectiveOpacity(t.el), fontSize: fs, fontWeight: weight, large, complex, text: t.text.slice(0, 60) };
      seen.set(key, entry);
      out.push(entry);
    }
    for (const r of t.vis) if (entry.rects.length < 8 && r.w >= 1 && r.h >= 1) entry.rects.push({ x: r.x, y: r.y, w: r.w, h: r.h });
  }
  // input values / placeholders
  for (const el of document.querySelectorAll('input:not([type=hidden]):not([type=checkbox]):not([type=radio]):not([type=range]):not([type=color]):not([type=file]),textarea,select')) {
    if (!RL.isVisible(el) || RL.isIgnored(el, 'contrast') || RL.isDisabled(el)) continue;
    const s = RL.cs(el);
    const hasValue = el.tagName === 'SELECT' ? true : !!el.value;
    const placeholder = !hasValue && el.placeholder;
    if (!hasValue && !placeholder) continue;
    const ps = placeholder ? getComputedStyle(el, '::placeholder') : s;
    const pb = RL.paddingBox(el);
    const pad = { l: parseFloat(s.paddingLeft), r: parseFloat(s.paddingRight) };
    const fs = parseFloat(s.fontSize) || 16;
    const h = Math.min(pb.h, fs * 1.3);
    const rect = { x: pb.x + pad.l, y: pb.y + (pb.h - h) / 2, w: Math.max(4, Math.min(pb.w - pad.l - pad.r, fs * 0.55 * ((placeholder || el.value || 'xxxxxxxx').length))), h };
    out.push({ idx: out.length, el, rects: [rect], color: RL.parseColor(ps.color), opacity: RL.effectiveOpacity(el), fontSize: fs, fontWeight: parseInt(s.fontWeight, 10) || 400, large: fs >= 24, complex: false, text: (placeholder || el.value || '').slice(0, 60), placeholder: !!placeholder });
  }
  return out;
};

RL.contrastSuggestion = function (fg, bg, target) {
  // Move fg lightness toward black or white until the target ratio is met.
  const toward = RL.luminance(bg) > 0.4 ? 0 : 255;
  for (let t = 0; t <= 1.0001; t += 0.02) {
    const c = { r: fg.r + (toward - fg.r) * t, g: fg.g + (toward - fg.g) * t, b: fg.b + (toward - fg.b) * t, a: 1 };
    if (RL.contrast(c, bg) >= target) return RL.hex(c);
  }
  return toward === 0 ? '#000000' : '#ffffff';
};

RL.rule({
  id: 'contrast',
  domOnly: true, // the Node runner replaces this with screenshot-based measurement
  run(ctx) {
    for (const c of RL.contrastCandidates(ctx.texts)) {
      if (c.complex || !c.color) continue;
      const bg = RL.backgroundOf(c.el);
      if (!bg) continue;
      const fg = RL.blend({ ...c.color, a: c.color.a * c.opacity }, bg);
      const ratio = RL.contrast(fg, bg);
      const need = c.large ? 3 : 4.5;
      if (ratio + 0.005 < need) {
        ctx.report({
          rule: 'contrast', el: c.el, severity: c.placeholder ? 'warn' : undefined,
          message: (ratio < 1.5 ? 'Text is practically invisible: ' : 'Low contrast: ') + ratio.toFixed(2) + ':1 (needs ' + need + ':1) — ' + RL.hex(fg) + ' on ' + RL.hex(bg) + '.',
          details: { ratio: +ratio.toFixed(2), required: need, fg: RL.hex(fg), bg: RL.hex(bg), suggestion: RL.contrastSuggestion(fg, bg, need) },
        });
      }
    }
  },
});

// ---------------------------------------------------------------------------
// Focus indicators (run as a separate phase because it changes focus).
RL.focusCheck = function (limit) {
  const issues = [];
  const style = document.createElement('style');
  style.textContent = '*,*::before,*::after{transition:none!important;animation-play-state:paused!important}';
  document.head.appendChild(style);
  const props = ['outlineStyle', 'outlineWidth', 'outlineColor', 'boxShadow', 'borderTopColor', 'borderBottomColor', 'borderBottomWidth', 'backgroundColor', 'color', 'textDecorationLine', 'transform', 'filter', 'opacity'];
  const scope = RL.inScope();
  const els = RL.allElements().filter((el) => scope(el) && RL.isInteractive(el) && RL.isVisible(el) && !RL.isDisabled(el) && el.tabIndex >= 0 && !RL.isIgnored(el, 'focus-indicator'));
  const seenSig = new Set();
  let n = 0;
  const prev = document.activeElement;
  for (const el of els) {
    if (n >= (limit || 40)) break;
    // only test one element per visual "kind" to keep this fast
    const sig = el.tagName + '|' + (typeof el.className === 'string' ? el.className : '');
    if (seenSig.has(sig)) continue;
    seenSig.add(sig);
    n++;
    const before = getComputedStyle(el);
    const b = {}; props.forEach((p) => { b[p] = before[p]; });
    const beforeAfter = getComputedStyle(el, '::after').boxShadow + getComputedStyle(el, '::after').outlineStyle + getComputedStyle(el, '::before').opacity;
    const wrap = el.parentElement;
    const wrapBefore = wrap ? getComputedStyle(wrap).boxShadow + getComputedStyle(wrap).outlineStyle + getComputedStyle(wrap).borderTopColor : '';
    el.focus({ preventScroll: true, focusVisible: true });
    if (document.activeElement !== el && !(document.activeElement && el.contains(document.activeElement))) continue;
    const after = getComputedStyle(el);
    const changed = props.some((p) => after[p] !== b[p]);
    const outlineVisible = after.outlineStyle !== 'none' && parseFloat(after.outlineWidth) > 0;
    const pseudoChanged = beforeAfter !== getComputedStyle(el, '::after').boxShadow + getComputedStyle(el, '::after').outlineStyle + getComputedStyle(el, '::before').opacity;
    const wrapChanged = wrap ? wrapBefore !== getComputedStyle(wrap).boxShadow + getComputedStyle(wrap).outlineStyle + getComputedStyle(wrap).borderTopColor : false;
    el.blur();
    if (!changed && !outlineVisible && !pseudoChanged && !wrapChanged) {
      issues.push({ rule: 'focus-indicator', ...RL.issueBase(el), message: 'No visible focus indicator: keyboard users cannot see when this ' + el.tagName.toLowerCase() + ' is focused (outline removed with no replacement).' });
    }
  }
  if (prev && prev.focus) try { prev.focus({ preventScroll: true }); } catch (e) { /* ignore */ }
  style.remove();
  return issues;
};

// ---- rules/forms.js
// Form-control polish: controls that render, but are built wrong. Stretched
// checkboxes, icons drawn over input text, squashed inputs, mismatched control
// heights, off-center icons. The dropdown-arrow rule needs pixels: candidates
// are collected here and measured from a screenshot (src/controls.js).

const TEXT_TYPES = /^(text|search|email|password|url|tel|number|date|datetime-local|month|time|week)$/;
function isTextField(el) {
  const t = el.tagName;
  if (t === 'TEXTAREA' || t === 'SELECT') return true;
  return t === 'INPUT' && TEXT_TYPES.test((el.getAttribute('type') || 'text').toLowerCase());
}
RL.isTextField = isTextField;

function boxes(el) {
  const r = RL.rectOf(el), s = RL.cs(el);
  const px = (k) => parseFloat(s[k]) || 0;
  const inner = { x: r.x + px('borderLeftWidth'), y: r.y + px('borderTopWidth'), right: r.right - px('borderRightWidth'), bottom: r.bottom - px('borderBottomWidth') };
  const content = { x: inner.x + px('paddingLeft'), y: inner.y + px('paddingTop'), right: inner.right - px('paddingRight'), bottom: inner.bottom - px('paddingBottom') };
  for (const b of [inner, content]) { b.w = b.right - b.x; b.h = b.bottom - b.y; }
  return { r, inner, content };
}

// Line boxes of the text inside `root`, skipping `skip`'s subtree.
function textLines(root, skip, max) {
  const lines = [];
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  for (let n = walker.nextNode(); n && lines.length < (max || 8); n = walker.nextNode()) {
    if (!n.data.trim() || (skip && skip.contains(n)) || !n.parentElement || !RL.isVisible(n.parentElement)) continue;
    const range = document.createRange();
    range.selectNodeContents(n);
    for (const q of range.getClientRects()) if (q.width > 1 && q.height > 1) lines.push(RL.docRect(q));
  }
  return lines;
}

function labelFor(el) {
  const wrap = el.closest('label');
  if (wrap) return wrap;
  if (el.labels && el.labels.length) return el.labels[0];
  for (let s = el.nextElementSibling; s; s = s.nextElementSibling) if ((s.textContent || '').trim()) return s;
  return null;
}

RL.rule({
  id: 'checkbox-layout',
  run(ctx) {
    for (const el of ctx.elements) {
      if (el.tagName !== 'INPUT' || !/^(checkbox|radio)$/.test(el.type)) continue;
      if (!RL.isVisible(el) || RL.isIgnored(el, 'checkbox-layout')) continue;
      const r = RL.rectOf(el);
      if (r.w < 4 || r.h < 4) continue;
      const kind = el.type === 'radio' ? 'radio button' : 'checkbox';
      if (r.w > 2 * r.h && r.w > 32 && r.h <= 48) {
        ctx.report({ rule: 'checkbox-layout', el, message: 'A ' + kind + ' is stretched to ' + Math.round(r.w) + 'px wide, so the box is drawn in the middle of that space, away from its label (usually a global `input { width: 100% }`).', details: { width: Math.round(r.w), height: Math.round(r.h) } });
        continue;
      }
      const s = RL.cs(el);
      if (s.position === 'absolute' || s.position === 'fixed') continue;
      const label = labelFor(el);
      if (!label) continue;
      const first = textLines(label, el, 1)[0];
      if (!first) continue;
      // The label's first line starts below the box: the box sits on a row of its own.
      if (first.y >= r.bottom - 1 && first.y - r.bottom < 80) {
        ctx.report({ rule: 'checkbox-layout', el, related: label, message: 'The ' + kind + ' sits on its own row above its label instead of beside it.', details: { gap: Math.round(first.y - r.bottom) } });
      }
    }
  },
});

RL.rule({
  id: 'input-icon-overlap',
  run(ctx) {
    for (const el of ctx.elements) {
      if (!isTextField(el) || el.tagName === 'TEXTAREA' || !RL.isVisible(el) || RL.isIgnored(el, 'input-icon-overlap')) continue;
      const { content } = boxes(el);
      if (content.w <= 0 || content.h <= 0) continue;
      // Icons are siblings drawn on top of the field (inside a relative wrapper).
      const scope = el.parentElement && el.parentElement.parentElement ? el.parentElement : null;
      if (!scope) continue;
      for (const icon of scope.querySelectorAll('svg, img, i, [class*="icon" i]')) {
        if (icon.contains(el) || (icon.parentElement && icon.parentElement.closest('svg')) || !RL.isVisible(icon)) continue;
        const ir = RL.rectOf(icon);
        if (ir.w < 6 || ir.h < 6 || ir.w > 40 || ir.h > 40) continue;
        const hit = RL.intersect(ir, content);
        if (!hit || hit.w < 4 || hit.h < ir.h * 0.5) continue;
        const left = ir.x + ir.w / 2 < content.x + content.w / 2;
        ctx.report({ rule: 'input-icon-overlap', el, related: icon, message: 'An icon is drawn over the area where the field shows its text and placeholder (' + Math.round(hit.w) + 'px of overlap on the ' + (left ? 'left' : 'right') + '). Typed text will run underneath it.', details: { overlap: Math.round(hit.w), side: left ? 'left' : 'right' } });
        break;
      }
    }
  },
});

RL.rule({
  id: 'squashed-control',
  run(ctx) {
    for (const el of ctx.elements) {
      if (!isTextField(el) || el.tagName === 'TEXTAREA' || !RL.isVisible(el) || RL.isIgnored(el, 'squashed-control')) continue;
      const fs = parseFloat(RL.cs(el).fontSize) || 16;
      const { r, inner, content } = boxes(el);
      if (r.h < 4 || r.w < 20) continue;
      // A <select> keeps its padding and clips the text; an <input> drops padding
      // that doesn't fit and centers the text, which only breaks once the box is
      // shorter than the glyphs and they run into the border.
      const select = el.tagName === 'SELECT';
      const room = select ? content.h : inner.h;
      if (room < fs * (select ? 0.9 : 1.1)) {
        ctx.report({ rule: 'squashed-control', el, message: 'The field is too short for its text: ' + Math.max(0, Math.round(room)) + 'px of room ' + (select ? 'inside the padding' : 'inside the border') + ' for ' + Math.round(fs) + 'px text, so the text is ' + (select ? 'cut off at the top and bottom' : 'squeezed against the border') + '.', details: { room: Math.round(room), fontSize: fs, height: Math.round(r.h) } });
      }
    }
  },
});

function isControlBox(el) {
  const t = el.tagName;
  if (t === 'INPUT') {
    const type = (el.getAttribute('type') || 'text').toLowerCase();
    if (!TEXT_TYPES.test(type) && !/^(submit|button|reset)$/.test(type)) return false;
  } else if (t !== 'SELECT' && t !== 'BUTTON' && el.getAttribute('role') !== 'combobox') {
    if (t !== 'A' || RL.isInline(el)) return false; // button-styled links only
    if ((el.textContent || '').trim().length > 40) return false;
  }
  return RL.hasVisibleBoundary(el);
}

// A box that hugs its controls (segmented control, input group) is what lines up visually.
function groupFrame(el, h) {
  let p = el.parentElement;
  for (let i = 0; i < 3 && p && p !== document.body; i++, p = p.parentElement) {
    if (!RL.hasVisibleBoundary(p)) continue;
    const ph = p.getBoundingClientRect().height;
    const onlyControls = Array.from(p.children).every((c) => /^(BUTTON|INPUT|SELECT|LABEL)$/.test(c.tagName) || /^(radio|tab|button)$/.test(c.getAttribute('role') || ''));
    return onlyControls && ph >= h && ph < h + 16 ? p : null;
  }
  return null;
}

RL.rule({
  id: 'control-height-mismatch',
  run(ctx) {
    const items = [];
    const seen = new Set();
    for (let el of ctx.elements) {
      if (!isControlBox(el) || !RL.isVisible(el) || RL.isIgnored(el, 'control-height-mismatch')) continue;
      let r = RL.rectOf(el);
      if (r.h < 24 || r.h > 80 || r.w < 24) continue;
      const frame = groupFrame(el, r.h);
      if (frame) { el = frame; r = RL.rectOf(frame); }
      if (seen.has(el)) continue;
      seen.add(el);
      // Boxes that grow with wrapped content (chips in a multi-select, two-line buttons) are taller by design.
      if (!isTextField(el)) {
        const ls = textLines(el, null, 12);
        if (ls.some((q) => q.y > ls[0].y + ls[0].h * 0.6)) continue;
      }
      items.push({ el, r });
    }
    items.sort((a, b) => a.r.x - b.r.x);
    const done = new Set();
    for (const a of items) {
      for (const b of items) {
        if (a === b || done.has(a.el) || done.has(b.el)) continue;
        const gap = b.r.x - a.r.right;
        if (gap < -1 || gap > 24) continue;
        if (RL.containsComposed(a.el, b.el) || RL.containsComposed(b.el, a.el)) continue;
        const ov = Math.min(a.r.bottom, b.r.bottom) - Math.max(a.r.y, b.r.y);
        const lo = Math.min(a.r.h, b.r.h), hi = Math.max(a.r.h, b.r.h);
        if (ov < lo * 0.5 || hi - lo < 4 || (hi - lo) / hi < 0.08) continue;
        done.add(a.el); done.add(b.el);
        ctx.report({ rule: 'control-height-mismatch', el: a.el, related: b.el, message: 'Controls side by side have different heights (' + Math.round(a.r.h) + 'px and ' + Math.round(b.r.h) + 'px), so their edges don\'t line up.', details: { heights: [Math.round(a.r.h), Math.round(b.r.h)] } });
      }
    }
  },
});

RL.rule({
  id: 'icon-misaligned',
  run(ctx) {
    for (const el of ctx.elements) {
      if (el.tagName.toLowerCase() !== 'svg' || (el.parentElement && el.parentElement.closest('svg'))) continue;
      if (!RL.isVisible(el) || RL.isIgnored(el, 'icon-misaligned')) continue;
      const ir = RL.rectOf(el);
      if (ir.w < 8 || ir.h < 8 || ir.w > 32 || ir.h > 32) continue;
      // The nearest non-empty sibling on either side must be a single line of text.
      let lines = null;
      for (const dir of ['previousSibling', 'nextSibling']) {
        let n = el[dir];
        while (n && n.nodeType === 3 && !n.data.trim()) n = n[dir];
        if (!n || (n.nodeType === 1 && (n.tagName.toLowerCase() === 'svg' || !RL.isVisible(n)))) continue;
        let ls;
        if (n.nodeType === 3) { const range = document.createRange(); range.selectNodeContents(n); ls = Array.from(range.getClientRects()).filter((q) => q.width > 1).map(RL.docRect); }
        else ls = textLines(n, null, 4);
        if (!ls.length || ls.some((q) => Math.abs(q.y - ls[0].y) > 2)) continue;
        const near = ls.reduce((best, q) => (Math.max(q.x - ir.right, ir.x - q.right) < Math.max(best.x - ir.right, ir.x - best.right) ? q : best));
        if (Math.max(near.x - ir.right, ir.x - near.right) > 16) continue;
        if (Math.min(near.bottom, ir.bottom) - Math.max(near.y, ir.y) <= 0) continue;
        lines = near;
        break;
      }
      if (!lines) continue;
      const diff = (ir.y + ir.h / 2) - (lines.y + lines.h / 2);
      if (Math.abs(diff) > Math.max(3, lines.h * 0.2)) {
        ctx.report({ rule: 'icon-misaligned', el, message: 'The icon sits ' + Math.round(Math.abs(diff)) + 'px ' + (diff < 0 ? 'above' : 'below') + ' the center of the text next to it.', details: { offset: Math.round(diff) } });
      }
    }
  },
});

// Dropdown-arrow candidates for the pixel pass: single-value selects and
// select-like triggers that draw a box.
RL.dropdownCandidates = function () {
  RL.resetCaches();
  const out = [];
  for (const el of document.querySelectorAll('select, [role="combobox"], [aria-haspopup="listbox"]')) {
    if (el.tagName === 'SELECT' ? (el.multiple || el.size > 1) : el.tagName === 'INPUT') continue;
    if (!RL.isVisible(el) || RL.isIgnored(el, 'dropdown-arrow') || RL.isDevTool(el)) continue;
    const { r, inner } = boxes(el);
    if (r.w < 60 || r.h < 24 || r.h > 80 || !RL.hasVisibleBoundary(el)) continue;
    const s = RL.cs(el);
    out.push({ inner, radius: parseFloat(s.borderTopRightRadius) || 0, native: el.tagName === 'SELECT' && s.appearance !== 'none', base: RL.issueBase(el) });
    if (out.length >= 40) break;
  }
  return out;
};

// ---- rules/popups.js
// Open dropdowns, menus, listboxes and popovers that can't be seen: cut off by a
// container's overflow, or painted underneath another element (z-index / stacking order).
// The rule checks the ones open now (a `states` entry, a Playwright test, the live overlay);
// the runner also opens each menu trigger on the page and checks what it opens.

const POPUP_SEL = '[role=menu],[role=listbox],[role=tree],.dropdown-menu.show,[popover],details[open]>:not(summary)';
const ITEM_SEL = '[role=option],[role=menuitem],[role=menuitemcheckbox],[role=menuitemradio],[role=treeitem],.dropdown-item,a[href],button,li';
const TRIGGER_SEL = '[aria-haspopup]:not([aria-haspopup=false]):not([aria-haspopup=dialog]),[role=combobox]:not(select),[data-bs-toggle=dropdown],[data-toggle=dropdown],details>summary';

function isOpenPopup(el) {
  if (!RL.isVisible(el)) return false;
  if (el.hasAttribute('popover')) { try { if (!el.matches(':popover-open')) return false; } catch (e) { return false; } return true; }
  // a dropdown floats: it, or a wrapper close above it, is positioned out of flow (an always-visible list isn't a dropdown)
  for (let n = el, d = 0; n && n !== document.body && d < 4; n = RL.parentOf(n), d++) {
    const p = RL.cs(n).position;
    if (p === 'absolute' || p === 'fixed') return true;
  }
  return false;
}

RL.openPopups = function () {
  const out = [];
  for (const el of document.querySelectorAll(POPUP_SEL)) {
    if (out.some((o) => o.contains(el))) continue; // a submenu inside an open menu: checked with it
    if (isOpenPopup(el)) out.push(el);
  }
  return out;
};

// The element the popup's own stacking order is decided by: its nearest ancestor that starts a stacking context.
function stackingRoot(el) {
  for (let n = RL.parentOf(el); n && n !== document.documentElement; n = RL.parentOf(n)) {
    if (n.nodeType !== 1) continue;
    const s = RL.cs(n);
    const parent = RL.parentOf(n);
    const flexItem = parent && parent.nodeType === 1 && /flex|grid/.test(RL.cs(parent).display);
    const why = s.zIndex !== 'auto' && (s.position !== 'static' || flexItem) ? 'z-index: ' + s.zIndex
      : s.transform !== 'none' ? 'transform' : s.filter !== 'none' ? 'filter' : parseFloat(s.opacity) < 1 ? 'opacity'
        : s.isolation === 'isolate' ? 'isolation' : /transform|opacity|filter/.test(s.willChange || '') ? 'will-change'
          : /paint|strict|content/.test(s.contain || '') ? 'contain' : s.position === 'fixed' || s.position === 'sticky' ? 'position: ' + s.position : null;
    if (why) return { el: n, why };
  }
  return null;
}

// Does this element contain fixed-position descendants (a transform, filter, perspective or contain on it)?
function trapsFixed(s) {
  return s.transform !== 'none' || s.filter !== 'none' || s.perspective !== 'none' || (s.backdropFilter && s.backdropFilter !== 'none') ||
    /paint|layout|strict|content/.test(s.contain || '') || /transform|filter|perspective/.test(s.willChange || '');
}

// What clips an item that isn't painted at a document point: 'inside' when the popup itself (or a box in it)
// scrolls it out of view, which is by design; else the ancestor outside the popup that cuts it off. Follows
// the containing blocks: an absolutely positioned box is only clipped by positioned ancestors' overflow, and a
// fixed one only inside a transformed (or filtered…) ancestor.
function clipperAt(item, popup, x, y) {
  let inside = true, pos = RL.cs(item).position;
  let n = RL.parentOf(item);
  while (n && n !== document.body && n !== document.documentElement) {
    if (n.nodeType !== 1) { n = RL.parentOf(n); continue; }
    const s = RL.cs(n);
    const contains = pos === 'fixed' ? trapsFixed(s) : pos === 'absolute' ? s.position !== 'static' || trapsFixed(s) : true;
    if (contains) {
      const clips = s.overflowX !== 'visible' || s.overflowY !== 'visible' || (s.clipPath && s.clipPath !== 'none');
      if (clips) {
        const r = RL.rectOf(n);
        if (x < r.x || x > r.right || y < r.y || y > r.bottom) {
          return inside ? 'inside' : { el: n, why: (s.clipPath && s.clipPath !== 'none' ? 'clip-path' : 'overflow: ' + (s.overflowY !== 'visible' ? s.overflowY : s.overflowX)) + (pos === 'fixed' && s.transform !== 'none' ? ', and its transform traps the fixed-position menu' : '') };
        }
      }
      pos = s.position === 'absolute' || s.position === 'fixed' ? s.position : 'static'; // what clips this containing block in turn
    }
    if (n === popup) inside = false;
    n = RL.parentOf(n);
  }
  return null;
}

// Hit-tests the popup's options. Returns a finding, or null when every option can be seen.
RL.popupProblem = function (popup, trigger) {
  if (RL.isIgnored(popup, 'popup-obscured') || (trigger && RL.isIgnored(trigger, 'popup-obscured'))) return null;
  let items = Array.from(popup.querySelectorAll(ITEM_SEL)).filter((i) => RL.isVisible(i) && !i.querySelector(ITEM_SEL));
  if (!items.length) items = [popup];
  items = items.slice(0, 30);
  const de = document.documentElement;
  const maxX = Math.max(de.scrollWidth, innerWidth), maxY = Math.max(de.scrollHeight, innerHeight);
  let hidden = 0, cut = null, cover = null, firstHidden = null;
  for (const item of items) {
    const r = RL.rectOf(item);
    if (r.w < 2 || r.h < 2) continue;
    let itemHidden = false;
    for (const fx of [0.5, 0.15, 0.85]) {
      const x = r.x + r.w * fx, y = r.y + r.h / 2;
      if (x < 0 || y < 0 || x >= maxX || y >= maxY) continue; // off the page: viewport-overflow's business
      const { stack } = RL.stackAt(x, y);
      const idx = stack.findIndex((e) => e === item || RL.containsComposed(item, e));
      if (idx < 0) {
        // not painted here at all: cut off by an ancestor's overflow (or clip-path), unless the popup scrolls it away itself
        const c = clipperAt(item, popup, x, y);
        if (c && c !== 'inside') { itemHidden = true; cut = cut || c; }
        continue;
      }
      for (let k = 0; k < idx; k++) {
        const e = stack[k];
        if (RL.containsComposed(popup, e) || RL.containsComposed(e, popup) || (trigger && (RL.containsComposed(trigger, e) || RL.containsComposed(e, trigger)))) continue;
        if (RL.isDevTool(e) || e.id === '__renderlint_overlay') continue;
        if (!RL.isOpaqueLayer(e)) continue;
        itemHidden = true;
        cover = cover || e;
        break;
      }
    }
    if (itemHidden) { hidden++; firstHidden = firstHidden || item; }
  }
  window.scrollTo({ left: 0, top: 0, behavior: 'instant' });
  if (!hidden) return null;
  const what = popup.matches('[role=listbox]') || (trigger && trigger.matches('[role=combobox],[aria-haspopup=listbox]')) ? 'dropdown list' : 'menu';
  const name = trigger ? RL.describe(trigger).text : '';
  const of = `${hidden} of ${items.length} ${items.length === 1 && items[0] === popup ? 'part' : 'option' + (items.length === 1 ? '' : 's')}`;
  const opened = 'The open ' + what + (name ? ` of "${name.slice(0, 40)}"` : '');
  if (cover) {
    const root = stackingRoot(popup);
    return {
      rule: 'popup-obscured', el: firstHidden, related: cover,
      message: `${opened} is drawn underneath another element (${of} hidden behind ${RL.selector(cover)}).` +
        (root ? ` Its z-index only counts inside ${RL.selector(root.el)} (${root.why}), which sits below that element.` : ''),
      details: { kind: 'covered', coveredBy: RL.selector(cover), hidden, items: items.length, ...(root ? { stackingContext: RL.selector(root.el), stackingReason: root.why } : {}) },
    };
  }
  return {
    rule: 'popup-obscured', el: firstHidden, related: cut ? cut.el : undefined,
    message: `${opened} is cut off${cut ? ` by ${RL.selector(cut.el)} (${cut.why})` : ''}: ${of} can't be seen.`,
    details: { kind: 'clipped', ...(cut ? { clippedBy: RL.selector(cut.el), clipReason: cut.why } : {}), hidden, items: items.length },
  };
};

RL.rule({
  id: 'popup-obscured',
  order: 93,
  run(ctx) {
    for (const popup of RL.openPopups()) {
      const p = hitTestable(() => RL.popupProblem(popup, null));
      if (p) ctx.report(p);
    }
  },
});

// For the runner: menu triggers on the page, two per repeated kind (the first and the last: the
// last row's menu is the one a table's overflow cuts off). Marks them for lookup, and marks the
// popups already open so the one a click opens can be told apart.
RL.menuTriggers = function (max) {
  RL.resetCaches(); // the page changed since the last look (a menu opened or closed)
  for (const p of document.querySelectorAll(POPUP_SEL)) p.setAttribute('data-rl-was-open', isOpenPopup(p) ? '1' : '0');
  const groups = new Map();
  for (const el of document.querySelectorAll(TRIGGER_SEL)) {
    if (!RL.isVisible(el) || RL.isDisabled(el) || el.getAttribute('aria-expanded') === 'true' || RL.isIgnored(el, 'popup-obscured')) continue;
    if (el.tagName === 'SUMMARY' && el.parentElement.open) continue;
    const href = el.tagName === 'A' ? (el.getAttribute('href') || '').trim() : '';
    if (href && href !== '#' && !/^javascript:/i.test(href)) continue; // a link that navigates
    const r = RL.rectOf(el);
    if (r.w < 4 || r.h < 4) continue;
    // the same kind of trigger in the same place (each row's "Actions"), whatever its text
    const sig = (n) => n.tagName + '.' + (typeof n.className === 'string' ? n.className.trim().split(/\s+/).sort().join('.') : '');
    const chain = [];
    for (let n = el, d = 0; n && n !== document.body && d < 5; n = n.parentElement, d++) chain.push(sig(n));
    const key = [chain.join('<'), el.getAttribute('aria-haspopup') || '', el.getAttribute('role') || ''].join('|');
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(el);
  }
  const picked = [];
  for (const list of groups.values()) {
    picked.push(list[0]);
    if (list.length > 1) picked.push(list[list.length - 1]);
  }
  return picked.slice(0, max || 8).map((el, i) => { el.setAttribute('data-rl-menu', String(i)); return '[data-rl-menu="' + i + '"]'; });
};

// After a trigger was clicked: the popup it opened, checked.
// Hit-testing sees only what can receive clicks. An open menu makes the rest of the page inert (Headless UI)
// or sets pointer-events: none on it (Radix, decorative layers), yet that still paints over the menu: lift both
// for the (synchronous) check, then put them back.
function hitTestable(fn) {
  const pe = document.createElement('style');
  pe.textContent = '*{pointer-events:auto!important}';
  document.head.appendChild(pe);
  const inert = Array.from(document.querySelectorAll('[inert]'));
  for (const e of inert) e.removeAttribute('inert');
  try { return fn(); } finally {
    for (const e of inert) e.setAttribute('inert', '');
    pe.remove();
  }
}

RL.checkMenu = function (sel) {
  RL.resetCaches(); // the page changed since the last look (a menu opened or closed)
  const trigger = document.querySelector(sel);
  if (!trigger) return null;
  return hitTestable(() => findAndCheck(trigger));
};
function findAndCheck(trigger) {
  let popup = null;
  for (const id of (trigger.getAttribute('aria-controls') || trigger.getAttribute('aria-owns') || '').split(/\s+/).filter(Boolean)) {
    const el = document.getElementById(id);
    if (el && RL.isVisible(el)) { popup = el.matches(POPUP_SEL) ? el : (el.querySelector('[role=listbox],[role=menu]') || el); break; }
  }
  if (!popup && trigger.tagName === 'SUMMARY') popup = Array.from(trigger.parentElement.children).find((c) => c !== trigger && RL.isVisible(c)) || null;
  if (!popup) popup = Array.from(document.querySelectorAll(POPUP_SEL)).find((p) => p.getAttribute('data-rl-was-open') !== '1' && isOpenPopup(p)) || null;
  if (!popup) return { open: false };
  const p = RL.popupProblem(popup, trigger);
  if (!p) return { open: true, issue: null };
  const { el, related, ...rest } = p;
  return { open: true, issue: { ...rest, ...RL.issueBase(el, related) } };
}

RL.menuStillOpen = function (sel) {
  RL.resetCaches(); // the page changed since the last look (a menu opened or closed)
  const trigger = document.querySelector(sel);
  if (!trigger) return false;
  if (trigger.tagName === 'SUMMARY') return trigger.parentElement.open;
  if (trigger.getAttribute('aria-expanded') === 'true') return true;
  return Array.from(document.querySelectorAll(POPUP_SEL)).some((p) => p.getAttribute('data-rl-was-open') !== '1' && isOpenPopup(p));
};

// ---- rules/loading.js
// What the user sees while the page waits for data (loading-state, action-feedback, error-feedback).
// The runner holds the page's fetch/XHR requests, takes RL.waitSnap('mark') a second into the wait,
// releases them, and takes RL.waitSnap('group') once the data is shown. The new content is grouped by
// the container it went into (the nearest element already there at the first look); the runner
// compares what each of those areas showed while waiting.

const LOADING_RE = /\b(loading|fetching|please wait|saving|submitting|processing|updating|refreshing|syncing|signing in|uploading|searching)\b|\b\w+ing\b.*(…|\.\.\.)$|\bwait\b.*(…|\.\.\.)$/i; // "Crunching numbers…", not "More…"
const NAME_RE = /skelet|spinner|\bspin\b|loader|loading|shimmer|placeholder|progress|pulse|busy/i;
const ERROR_RE = /\b(error|failed|failure|couldn['’]?t|could not|can['’]?t|cannot|unable|went wrong|try again|retry|problem|unavailable|offline|timed? ?out|denied|invalid)\b/i;

const shownEl = (el) => (el.checkVisibility ? el.checkVisibility({ opacityProperty: true, visibilityProperty: true }) : RL.isVisible(el));
const inViewR = (r) => r.width > 0 && r.height > 0 && r.bottom > 0 && r.right > 0 && r.top < innerHeight && r.left < innerWidth;
